"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["56178"],{33709(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.modo_de_deliberacao_invalido","status":422,"titulo":"O modo de delibera\xe7\xe3o deve ser colegiada com vota\xe7\xe3o ou ato individual"},"descricao":{"codigo":"uniplus.selecao.banca.modo_de_deliberacao_invalido","requisitos":["UNI-REQ-0275","UNI-REQ-0338"],"oQueAconteceu":["A recusa tamb\xe9m ocorre quando o c\xf3digo informado n\xe3o corresponde a uma das op\xe7\xf5es aceitas.","A regra de delibera\xe7\xe3o da banca informou um `modo` que n\xe3o pertence ao vocabul\xe1rio\\nde delibera\xe7\xe3o. O vocabul\xe1rio \xe9 fechado e tem dois modos:","- `COLEGIADA_COM_VOTACAO`: a banca decide por vota\xe7\xe3o, com qu\xf3rum, crit\xe9rio de\\n  decis\xe3o e forma de encerramento (UNI-REQ-0275);\\n- `ATO_INDIVIDUAL`: qualquer pessoa titular designada pratica o ato, sem vota\xe7\xe3o\\n  (UNI-REQ-0338). Ao lado do ato individual, a banca pode declarar a vota\xe7\xe3o usada no\\n  julgamento do recurso.","O modo escolhido define quais campos da regra existem. Quando o modo est\xe1 ausente, a mensagem pede seu preenchimento; quando o c\xf3digo \xe9 desconhecido, informa que ele n\xe3o \xe9 uma das op\xe7\xf5es dispon\xedveis. No ato individual, a banca pode declarar a vota\xe7\xe3o usada no julgamento do recurso. Um c\xf3digo desconhecido n\xe3o permite saber como a banca decide nem conferir os campos que dependem do modo.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.modo` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.modo` na banca da etapa."],"comoResolver":["Informe um dos dois modos. Use `COLEGIADA_COM_VOTACAO` quando o edital manda a banca\\nvotar e `ATO_INDIVIDUAL` quando o edital d\xe1 a decis\xe3o a quem pratica o ato\\nsozinho, como na banca de homologa\xe7\xe3o das inscri\xe7\xf5es. Depois de corrigido o modo,\\nos campos dele s\xe3o conferidos; no ato individual, a vota\xe7\xe3o do recurso \xe9 aceita, e a\\nvota\xe7\xe3o declarada pela metade tem\\n[recusa pr\xf3pria](/erros/uniplus.selecao.banca.votacao_do_recurso_incompleta)."],"ondeAparece":["- Defini\xe7\xe3o do cronograma de fases do processo seletivo\\n- Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);